    'class ProgressReporter:\n'
    '    """Console progress feedback for the whole run.\n'
    '\n'
    '    INTENT: a long multi-agent run spends most of its wall-clock inside\n'
    '    LLM calls, which print nothing. This class keeps the console ALIVE:\n'
    '      * begin()  -- banner (workflow, node count, prompt) + starts a\n'
    '                    HEARTBEAT thread that, every 15s, prints elapsed\n'
    '                    time, how many nodes are done, and which nodes are\n'
    '                    currently running (with their own elapsed time).\n'
    '      * node_start/node_done -- per-node ▶/✓ lines with a done-counter.\n'
    '      * waiting  -- fan-in status (how many inputs a node still needs).\n'
    '      * note     -- free-form step info (skill runs etc.).\n'
    '      * end()    -- stops the heartbeat and prints the run summary.\n'
    '    The heartbeat runs on a daemon thread so it can never block exit.\n'
    '    """\n'
    '\n'
    '    _t0 = None\n'
    '    _done = 0\n'
    '    _total = 0\n'
    '    _in_flight = {}   # node display name -> start time (monotonic)\n'
    '    _durations = {}   # node display name -> seconds spent (for the summary)\n'
    '    _stop = None      # threading.Event that terminates the heartbeat\n'
    '\n'
    '    @classmethod\n'
    '    def begin(cls, prompt):\n'
    '        """Print the run banner and start the liveness heartbeat."""\n'
    '        # Every node that reports done: agents (dispatchers included), code nodes, playbooks.\n'
    '        total = len(AGENTS) + len(globals().get("CODE_NODES", {})) + len(globals().get("PLAYBOOKS", {}))\n'
    '        cls._t0 = time.monotonic()\n'
    '        cls._total = total\n'
    '        print("=" * 74, flush=True)\n'
    '        print(f"WORKFLOW  {WORKFLOW_NAME}  (id {WORKFLOW_ID})", flush=True)\n'
    '        print(f"  {total} node(s) + output sink", flush=True)\n'
    '        print(f"  prompt: {str(prompt)[:120]!r}", flush=True)\n'
    '        print("=" * 74, flush=True)\n'
