    '@dataclass\n'
    'class NodeMessage:\n'
    '    """The typed payload that flows along every edge of the graph.\n'
    '\n'
    '    INTENT: make the data contract between nodes explicit. Carrying the\n'
    '    SOURCE alongside the text lets a fan-in node label each contribution\n'
    '    and lets the fan-in barrier count distinct parents.\n'
    '    """\n'
    '    source_id: str      # editor node id of the producer\n'
    '    source_name: str    # human-readable node name (for input framing/logs)\n'
    '    text: str           # the producer\'s output\n'
    '    # DISPATCHER support. A dispatcher\'s outgoing edges are a MENU, not a\n'
    '    # fan-out: it broadcasts to every menu child (the graph\'s edges are\n'
    '    # fixed at build time) and names the one that should actually run.\n'
    '    # The others see a route_to that is not theirs and skip -- they still\n'
    '    # report downstream, which is what keeps the fan-in barriers of the\n'
    '    # nodes below them from waiting forever on a branch that never ran.\n'
    '    route_to: str = ""  # node id the dispatcher chose ("" = not a routed edge)\n'
    '    skipped: bool = False   # this branch was not chosen; text is empty\n'
    '    # CODE NODE exits: a code node with several exits names the children of the exit it took\n'
    '    # (None = not a routing node; () = an exit that leads nowhere, so nothing downstream runs).\n'
    '    routes: tuple | None = None\n'
    '    task: str = ""      # a dispatcher\'s own input (the email): what a code branch below it receives\n'
    '\n'
    '\n'
    '# Run-scoped state shared by all executors. The Start executor records the\n'
    '# original user prompt here so every agent node can include it in its input\n'
    '# framing (the graph edges only carry parent outputs, not the prompt).\n'
    'RUN_STATE = {"user_prompt": ""}\n'
    '\n'
    '\n'
    'def _delivers(m: "NodeMessage", node_id: str) -> bool:\n'
    '    """A parent\'s message reaches this node: the parent ran, and it does not route (a dispatcher\'s\n'
    '    choice, a code node\'s exit) or it routed here."""\n'
    '    if m.skipped:\n'
    '        return False\n'
    '    if m.route_to:\n'
    '        return m.route_to == node_id\n'
    '    return m.routes is None or node_id in m.routes\n'
    '\n'
    '\n'
    'def _skip_node(msgs: list, node_id: str) -> bool:\n'
    '    """Not on a taken branch: no parent\'s message reaches this node. A skipped node still reports\n'
    '    downstream, so every fan-in barrier below it completes."""\n'
    '    return bool(msgs) and not any(_delivers(m, node_id) for m in msgs)\n'
