    '\n'
    '\n'
    'class PlaybookNodeExecutor(Executor):\n'
    '    """A PLAYBOOK node as a MAF executor.\n'
    '\n'
    '    INTENT: schedule the shared interpreter in the right place in the\n'
    '    graph. The loop itself is NOT a MAF agent and must not be -- it runs\n'
