    '        if "_CURRENT_NODE" in globals():\n'
    '            _CURRENT_NODE.set(name)\n'
    '        reply = (await agent.run(self._framed_input())).text or ""\n'
    '        lines = [ln.strip() for ln in reply.strip().splitlines()]\n'
    '        first = lines[0].strip(\' "\\\'*`#:-\').lower() if lines else ""\n'
